namespace PC28168.U20241G031.OpenPay.Platform.Settlements.Interfaces.REST.Resources;

/// <summary>
/// Response DTO resource representing a created DisbursementOrder (Business Rule 14).
/// </summary>
/// <param name="Id">The autogenerated primary key identifier.</param>
/// <param name="OrderTrackingCode">The order tracking code as string.</param>
/// <param name="AffiliateStoreId">The affiliate store identifier as string.</param>
/// <param name="ScheduledFrom">The scheduled start date as string.</param>
/// <param name="ScheduledTo">The scheduled end date as string.</param>
/// <param name="TransferCapAmount">The transfer cap amount as decimal.</param>
/// <param name="TransferCapCurrencyCode">The transfer cap currency code as string.</param>
/// <param name="Status">The disbursement status as string.</param>
